<?php require __DIR__.'/includes/bootstrap.php';require_guest();$message='If that email belongs to an active account, password reset instructions will be sent.';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);if(!$email)$error='Enter a valid email address.';else{$s=db()->prepare('SELECT id FROM users WHERE email=? AND is_active=1');$s->execute([$email]);$u=$s->fetch();if($u){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);db()->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at,created_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE),NOW())')->execute([$u['id'],$hash]);$url=rtrim($GLOBALS['config']['mail']['reset_base_url'],'/').'?token='.urlencode($token);$body="Use this one-time link within 30 minutes:\n\n".$url."\n\nIf you did not request this, ignore this message.";$sent=@mail($email,'Password reset',$body,'From: '.$GLOBALS['config']['mail']['from']);if(!$sent){error_log('Password reset email delivery failed; user_id='.(int)$u['id']);}}flash('info',$message);redirect('forgot_password.php');}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forgot password</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="panel auth"><h1>Forgot password</h1><?php show_flashes();if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="field"><label>Email address</label><input type="email" name="email" required></div><button>Send reset link</button></form><p><a href="login.php">Back to login</a></p><p class="help">Configure outbound email on the server. Response does not reveal whether an account exists.</p></main></body></html>